// 统计幸运子串数量的函数
long long countLucky(const string& s, int k) {
    int n = (int)s.size();
    vector<int> pre(n + 1, 0);               // 前缀和
    for (int i = 0; i < n; ++i) pre[i + 1] = pre[i] + (s[i] - '0');
    int half = k / 2;
    long long ans = 0;
    for (int l = 0; l + k <= n; ++l) {
        int sum1 = pre[l + half] - pre[l];        // 前半部分和
        int sum2 = pre[l + k] - pre[l + half];    // 后半部分和
        if (sum1 == sum2) ++ans;
    }
    return ans;
}

